/**
 * Discovery documents for delegated auth.
 *
 * - RFC 9728 protected resource metadata for the MCP server (path form, probed first, and the root
 *   fallback), generated by @app/conventions `mcpDiscovery` now that an authorization server exists.
 *   Plus the path form for the HTTP API resource (`/.well-known/oauth-protected-resource/api`).
 * - RFC 8414 authorization server metadata at `/.well-known/oauth-authorization-server`
 *   (issuer = origin, no path). `code_challenge_methods_supported: ["S256"]` is what MCP clients
 *   check before they proceed; `client_id_metadata_document_supported` advertises CIMD; there is
 *   no `registration_endpoint` because DCR is not offered.
 */
import {
  type AuthHints,
  cliCommand,
  type JsonValue,
  mcpDiscovery,
  type WellKnownDocument,
} from "@app/conventions";
import { IntegrationScope } from "@app/domain";
import { DELEGABLE_SCOPES } from "./scopes.js";
import { OAUTH_PATHS, type OAuthUrls } from "./urls.js";

export const DEVICE_GRANT_TYPE = "urn:ietf:params:oauth:grant-type:device_code";

export function authorizationServerMetadata(urls: OAuthUrls): { [key: string]: JsonValue } {
  return {
    issuer: urls.issuer,
    authorization_endpoint: urls.authorize,
    token_endpoint: urls.token,
    revocation_endpoint: urls.revoke,
    device_authorization_endpoint: urls.deviceCode,
    response_types_supported: ["code"],
    response_modes_supported: ["query"],
    grant_types_supported: ["authorization_code", "refresh_token", DEVICE_GRANT_TYPE],
    code_challenge_methods_supported: ["S256"],
    // "none": public clients (agents, CLI, public integrations); secrets: confidential integrations.
    token_endpoint_auth_methods_supported: ["none", "client_secret_basic", "client_secret_post"],
    revocation_endpoint_auth_methods_supported: [
      "none",
      "client_secret_basic",
      "client_secret_post",
    ],
    // Agent scopes, then integration scopes (src/integrations/scopes.ts).
    scopes_supported: [...new Set<string>([...DELEGABLE_SCOPES, ...IntegrationScope.options])],
    client_id_metadata_document_supported: true,
    authorization_response_iss_parameter_supported: true,
    service_documentation: `${urls.origin}/start`,
  };
}

/** The RFC 9728 documents this deployment serves (MCP path + root fallback, and the HTTP API). */
export function protectedResourceDocuments(urls: OAuthUrls, version: string): WellKnownDocument[] {
  const docs = mcpDiscovery({
    host: urls.origin,
    mcpUrl: urls.mcpResource,
    version,
    authorizationServers: [urls.issuer],
    scopes: DELEGABLE_SCOPES,
  }).filter((d) => d.path.startsWith("/.well-known/oauth-protected-resource"));
  const mcpDoc = docs[0];
  if (mcpDoc) {
    docs.push({
      ...mcpDoc,
      path: "/.well-known/oauth-protected-resource/api",
      body: { ...mcpDoc.body, resource: urls.apiResource, resource_name: "gittifacts HTTP API" },
      spec: "RFC 9728 (HTTP API resource, path form)",
    });
  }
  return docs;
}

export const AS_METADATA_PATH = OAUTH_PATHS.asMetadata;

/**
 * The CLI login (`packages/cli`): RFC 8628 against `device_authorization_endpoint`
 * (POST /api/auth/device/code, client_id=gittifacts-cli) and `token_endpoint` (/api/oauth/token),
 * both discovered from /.well-known/oauth-authorization-server.
 */
export function deviceFlowCommand(origin: string): string {
  // The CLI tarball this platform serves (/cli/gittifacts.tgz); `npx gittifacts` once on npm.
  return cliCommand(origin, "login");
}

/** The delegated-auth part of `/start` and `/llms.txt` (@app/conventions `authHints`). */
export function delegatedAuthHints(origin: string): Pick<AuthHints, "oauth" | "deviceFlowCommand"> {
  return { oauth: true, deviceFlowCommand: deviceFlowCommand(origin) };
}
